// Demo fixtures: one adult learner ("Sam"), one coach ("Priya", an occupational therapist),
// a six-step morning routine and 21 days of SYNTHETIC history. Every seeded event carries
// `seeded: true`, and the coach report prints how many runs are seeded, so the demo never
// passes synthetic history off as real usage.
//
// History is generated by driving the real engine commands day by day (not by writing levels
// directly), so the seeded levels are exactly what the fading policy would have produced.

import { apply, cmdComplete, cmdHelp, cmdStartRun, emptyState, type Ctx } from '../core/engine.ts';
import { DEFAULT_POLICY, type NewEvent, type PersonState, type RoutineDef, type ScaffoldEvent } from '../core/model.ts';

