/**
 * Per-step outcome scripts for days 1..21. 'u' = done without help, 'a' = asked for help.
 * They are chosen to show (a) steady fading, (b) a step that plateaus at a cue, and
 * (c) a step where support is added back after a rough patch — the "needs attention" case.
 */
export const OUTCOMES: Record<string, string> = {
  teeth:     'auuuuuuuuuuuuuuuuuuuu',
  face:      'uuuauuuuuuuuuuuuuuuuu',
  dress:     'aaauuuauuuauuauuauuau',
  breakfast: 'uuuuuuuuuuuuuuuuuuuuu',
  bag:       'uuuuuuauuuuuuuuuaaaau',
  door:      'aaaauuuauuuauuauuauua',
};
export const SEED_DAYS = 21;

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Offset (ms) of `timeZone` from UTC at instant `utcMs`. */
function tzOffsetMs(utcMs: number, timeZone: string): number {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    })
      .formatToParts(new Date(utcMs))
      .map((p) => [p.type, p.value]),
  );
  const asUtc = Date.UTC(+parts.year!, +parts.month! - 1, +parts.day!, +parts.hour!, +parts.minute!, +parts.second!);
  return asUtc - utcMs;
}

/** UTC instant for a wall-clock time on a calendar date in `timeZone`. */
export function zonedToUtc(ymd: string, hh: number, mm: number, timeZone: string): number {
  const [y, m, d] = ymd.split('-').map(Number) as [number, number, number];
  const guess = Date.UTC(y, m - 1, d, hh, mm);
  const off = tzOffsetMs(guess, timeZone);
  const t = guess - off;
  return t - (tzOffsetMs(t, timeZone) - off);
}

/** Calendar date (YYYY-MM-DD) of an instant in `timeZone`. */
export function localYmd(utcMs: number, timeZone: string): string {
  return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(utcMs));
}

export function addDays(ymd: string, n: number): string {
  const [y, m, d] = ymd.split('-').map(Number) as [number, number, number];
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

export interface SeedOptions {
  /** Local calendar date of "today"; history covers the 21 days before it. */
  today: string;
  timeZone: string;
  /** Stream to seed; defaults to the shared demo person. Sandboxes use their own id. */
  personId?: string;
  /** Demo clock stored in the stream itself (so every server instance agrees on "now"). */
  demoClock?: { anchorMs: number; startedMs: number };
}

/**
 * Builds the complete seeded event list (without store sequence numbers it would be ambiguous
 * to replay, so sequence numbers are assigned here, starting at 1).
 */
export function buildSeedEvents(opts: SeedOptions): ScaffoldEvent[] {
  const rnd = mulberry32(20261017);
  const events: ScaffoldEvent[] = [];
  const personId = opts.personId ?? DEMO_PERSON.personId;
  const state: PersonState = emptyState(personId);
  const push = (e: NewEvent) => {
    const full = { ...e, seq: events.length + 1, seeded: true } as ScaffoldEvent;
    events.push(full);
    apply(state, full, { timeZone: opts.timeZone });
  };
  const day0 = addDays(opts.today, -(SEED_DAYS + 1)); // last seeded day = yesterday
  const setupAt = new Date(zonedToUtc(day0, 18, 0, opts.timeZone)).toISOString();
  push({
    type: 'person.registered',
    personId,
    displayName: DEMO_PERSON.displayName,
    coachIds: [DEMO_COACH.coachId],
    ...(opts.demoClock ? { demoClock: opts.demoClock } : {}),
    at: setupAt,
    actorId: personId,
  });
  push({ type: 'routine.published', routine: MORNING, version: 1, at: setupAt, actorId: personId });
  for (const routine of EVERYDAY_ROUTINES) push({ type: 'routine.published', routine, version: 1, at: setupAt, actorId: personId });

  let counter = 0;
  for (let day = 1; day <= SEED_DAYS; day++) {
    const ymd = addDays(day0, day);
    let t = zonedToUtc(ymd, 7, Math.floor(rnd() * 12), opts.timeZone);
    const ctx = (): Ctx => ({ now: new Date(t).toISOString(), actorId: personId, newId: (p) => `${p}-seed-${String(day).padStart(2, '0')}` });
    const started = cmdStartRun(state, ctx(), { routineRef: 'morning', device: day % 3 === 0 ? 'kitchen' : 'bedroom' });
    started.events.forEach(push);
    for (const step of MORNING.steps) {
      const outcome = OUTCOMES[step.id]![day - 1];
      if (outcome === 'a') {
        t += step.estSec * 1000 * (0.5 + rnd() * 0.2);
        cmdHelp(state, ctx(), { runId: started.runId }).events.forEach(push);
        t += step.estSec * 1000 * (0.7 + rnd() * 0.3);
      } else {
        t += step.estSec * 1000 * (0.8 + rnd() * 0.3);
      }
      counter++;
      cmdComplete(state, ctx(), { runId: started.runId, idempotencyKey: `seed-${counter}` }).events.forEach(push);
    }
  }
  return events;
}
